#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import subprocess
import sys
from pathlib import Path

SCRIPT_NAME = "apply_amado_ai_editor.py"
TARGETS = {'app/api/rewrite/route.ts': '', 'app/rewrite/page.tsx': '', 'docs/AMADO_ROADMAP.md': '', 'lib/editor/contracts.test.ts': '', 'lib/editor/contracts.ts': ''}
BASELINE_MARKERS = {
    "app/api/rewrite/route.ts": ["estimateUniqueness", "INTENSITY_INSTRUCTIONS"],
    "app/rewrite/page.tsx": ["const INTENSITIES", "Originalidade ~"],
    "docs/AMADO_ROADMAP.md": ["Lean AI-first roadmap", "Sprint 10 — Hardening"],
}


def run(command: list[str], *, check: bool = True) -> subprocess.CompletedProcess[str]:
    print("+", " ".join(command))
    return subprocess.run(command, text=True, check=check)


def ensure_repo() -> Path:
    root = Path.cwd()
    if not (root / ".git").exists():
        raise SystemExit("ERROR: run this script from the Amado repository root")
    branch = subprocess.check_output(["git", "branch", "--show-current"], text=True).strip()
    if branch != "main":
        raise SystemExit(f"ERROR: expected branch main, found {branch!r}")
    return root


def changed_paths() -> list[str]:
    raw = subprocess.check_output(["git", "status", "--short"], text=True)
    paths = []
    for line in raw.splitlines():
        if not line.strip():
            continue
        path = line[3:].strip()
        if " -> " in path:
            path = path.split(" -> ", 1)[1]
        paths.append(path)
    return paths


def check_clean(allow_targets: bool) -> None:
    allowed = {SCRIPT_NAME}
    if allow_targets:
        allowed.update(TARGETS)
    unexpected = [path for path in changed_paths() if path not in allowed]
    if unexpected:
        joined = "\n  ".join(unexpected)
        raise SystemExit(f"ERROR: unrelated local changes found:\n  {joined}")


def check_baseline(root: Path) -> None:
    for rel, markers in BASELINE_MARKERS.items():
        path = root / rel
        if not path.exists():
            raise SystemExit(f"ERROR: missing expected file: {rel}")
        text = path.read_text(encoding="utf-8")
        if all(marker in text for marker in markers):
            continue
        desired = base64.b64decode(TARGETS[rel]).decode("utf-8")
        if text == desired:
            continue
        raise SystemExit(f"ERROR: {rel} no longer matches the reviewed baseline; create a fresh Repomix before applying")


def write_targets(root: Path) -> None:
    for rel, encoded in TARGETS.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))
        print(f"wrote {rel}")


def verify(root: Path) -> None:
    for rel, encoded in TARGETS.items():
        path = root / rel
        expected = base64.b64decode(encoded)
        if not path.exists() or path.read_bytes() != expected:
            raise SystemExit(f"ERROR: verification mismatch: {rel}")

    run(["git", "diff", "--check"])
    run(["npx", "tsc", "--noEmit"])
    run(["npm", "run", "lint"])
    run(["npm", "run", "test"])
    run(["npm", "run", "build"])
    print("OK: editor patch and full repository verification passed")


def commit(root: Path) -> None:
    check_clean(allow_targets=True)
    verify(root)
    run(["git", "add", *TARGETS.keys()])
    staged = subprocess.check_output(["git", "diff", "--cached", "--name-only"], text=True).splitlines()
    unexpected = [path for path in staged if path not in TARGETS]
    if unexpected:
        raise SystemExit("ERROR: unrelated staged files found: " + ", ".join(unexpected))
    if not staged:
        print("Nothing to commit")
        return
    run(["git", "commit", "-m", "feat: add explainable AI text editor"])


def push(root: Path) -> None:
    check_clean(allow_targets=False)
    run(["git", "push", "origin", "main"])
    script_path = root / SCRIPT_NAME
    if script_path.exists() and script_path.resolve() == Path(__file__).resolve():
        script_path.unlink()
        print(f"removed temporary patch script {SCRIPT_NAME}")


def main() -> None:
    parser = argparse.ArgumentParser(description="Integrate the Amado AI editor")
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--check", action="store_true")
    group.add_argument("--apply", action="store_true")
    group.add_argument("--verify", action="store_true")
    group.add_argument("--commit", action="store_true")
    group.add_argument("--push", action="store_true")
    args = parser.parse_args()

    root = ensure_repo()
    if args.check:
        check_clean(allow_targets=False)
        check_baseline(root)
        print("OK: main branch, clean worktree, reviewed baseline detected")
    elif args.apply:
        check_clean(allow_targets=False)
        check_baseline(root)
        write_targets(root)
        print("OK: AI editor and updated roadmap applied")
    elif args.verify:
        check_clean(allow_targets=True)
        verify(root)
    elif args.commit:
        commit(root)
    elif args.push:
        push(root)


if __name__ == "__main__":
    main()
